import fs from "node:fs";
import path from "node:path";

const ROOT = process.cwd();
const FEATURE_DIR = path.join(ROOT, "src", "features", "forensicReconstruction");
const TYPES = path.join(FEATURE_DIR, "forensicInvestigationTypes.ts");
const SERVICE = path.join(FEATURE_DIR, "forensicInvestigationService.ts");
const WORKSPACE = path.join(FEATURE_DIR, "ForensicInvestigationWorkspace.tsx");
const COMPONENT = path.join(FEATURE_DIR, "HypothesesWorkspace.tsx");
const COMPONENT_CSS = path.join(FEATURE_DIR, "HypothesesWorkspace.css");

function fail(message) {
  console.error("\n[RoadSafe] " + message);
  process.exit(1);
}
for (const file of [TYPES, SERVICE, WORKSPACE]) {
  if (!fs.existsSync(file)) fail("Required file not found: " + path.relative(ROOT, file));
}

const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const backupDir = path.join(ROOT, ".roadsafe-ui-backup", "forensic-hypotheses-v1-" + stamp);
fs.mkdirSync(backupDir, { recursive: true });
for (const file of [TYPES, SERVICE, WORKSPACE, COMPONENT, COMPONENT_CSS]) {
  if (fs.existsSync(file)) fs.copyFileSync(file, path.join(backupDir, path.basename(file)));
}

let types = fs.readFileSync(TYPES, "utf8");
let service = fs.readFileSync(SERVICE, "utf8");
let workspace = fs.readFileSync(WORKSPACE, "utf8");

if (!types.includes("export interface ForensicCrashHypothesis")) {
  const anchor = "export interface ForensicAccidentInvestigation {";
  if (!types.includes(anchor)) fail("ForensicAccidentInvestigation anchor not found.");
  const block = `export type HypothesisStatus =
  | "Draft"
  | "Under review"
  | "Ready for simulation"
  | "Rejected"
  | "Superseded";

export interface ForensicHypothesisImpactRegion {
  xMetres: number;
  yMetres: number;
  radiusMetres: number;
  description: string;
}

export interface ForensicHypothesisEvent {
  id: string;
  order: number;
  description: string;
}

export interface ForensicCrashHypothesis {
  id: string;
  code: string;
  title: string;
  summary: string;
  status: HypothesisStatus;
  confidence: ForensicConfidence;
  provenance: "Investigator Assumption";
  supportingFindingIds: string[];
  conflictingFindingIds: string[];
  supportingEvidenceIds: string[];
  conflictingEvidenceIds: string[];
  sourceMeasurementIds: string[];
  sourceVehicleIds: string[];
  sourcePersonIds: string[];
  sourceWitnessIds: string[];
  assumptions: string[];
  missingEvidence: string[];
  impactRegion?: ForensicHypothesisImpactRegion;
  eventSequence: ForensicHypothesisEvent[];
  selectedForSimulation: boolean;
  notes: string;
  createdAt: string;
  updatedAt: string;
}

`;
  types = types.replace(anchor, block + anchor);
}

if (!types.includes("hypotheses: ForensicCrashHypothesis[];")) {
  const anchor = "  analysisFindings: ForensicAnalysisFinding[];";
  if (!types.includes(anchor)) fail("analysisFindings field anchor not found.");
  types = types.replace(anchor, anchor + "\n  hypotheses: ForensicCrashHypothesis[];");
}

if (!types.includes("export const HYPOTHESIS_STATUS_OPTIONS")) {
  const anchor = "export const FORENSIC_PROVENANCE_OPTIONS: ForensicProvenance[] = [";
  if (!types.includes(anchor)) fail("provenance options anchor not found.");
  const block = `export const HYPOTHESIS_STATUS_OPTIONS: HypothesisStatus[] = [
  "Draft",
  "Under review",
  "Ready for simulation",
  "Rejected",
  "Superseded",
];

`;
  types = types.replace(anchor, block + anchor);
}

if (!service.includes("  ForensicCrashHypothesis,")) {
  const anchor = "  ForensicAnalysisFinding,";
  if (!service.includes(anchor)) fail("service import anchor not found.");
  service = service.replace(anchor, anchor + "\n  ForensicCrashHypothesis,");
}

if (!service.includes("hypotheses: Array.isArray(record.hypotheses)")) {
  const anchor = `    analysisFindings: Array.isArray(record.analysisFindings)
      ? record.analysisFindings.map((finding) => ({
          ...finding,
          sourceEvidenceIds: Array.isArray(finding.sourceEvidenceIds) ? finding.sourceEvidenceIds : [],
          sourceMeasurementIds: Array.isArray(finding.sourceMeasurementIds) ? finding.sourceMeasurementIds : [],
          sourceVehicleIds: Array.isArray(finding.sourceVehicleIds) ? finding.sourceVehicleIds : [],
          sourcePersonIds: Array.isArray(finding.sourcePersonIds) ? finding.sourcePersonIds : [],
          sourceWitnessIds: Array.isArray(finding.sourceWitnessIds) ? finding.sourceWitnessIds : [],
          limitations: Array.isArray(finding.limitations) ? finding.limitations : [],
          usesSceneIntake: Boolean(finding.usesSceneIntake),
        }))
      : [],`;
  if (!service.includes(anchor)) fail("service normalise anchor differs from expected V2 state.");
  const block = `${anchor}
    hypotheses: Array.isArray(record.hypotheses)
      ? record.hypotheses.map((hypothesis) => ({
          ...hypothesis,
          provenance: "Investigator Assumption" as const,
          supportingFindingIds: Array.isArray(hypothesis.supportingFindingIds) ? hypothesis.supportingFindingIds : [],
          conflictingFindingIds: Array.isArray(hypothesis.conflictingFindingIds) ? hypothesis.conflictingFindingIds : [],
          supportingEvidenceIds: Array.isArray(hypothesis.supportingEvidenceIds) ? hypothesis.supportingEvidenceIds : [],
          conflictingEvidenceIds: Array.isArray(hypothesis.conflictingEvidenceIds) ? hypothesis.conflictingEvidenceIds : [],
          sourceMeasurementIds: Array.isArray(hypothesis.sourceMeasurementIds) ? hypothesis.sourceMeasurementIds : [],
          sourceVehicleIds: Array.isArray(hypothesis.sourceVehicleIds) ? hypothesis.sourceVehicleIds : [],
          sourcePersonIds: Array.isArray(hypothesis.sourcePersonIds) ? hypothesis.sourcePersonIds : [],
          sourceWitnessIds: Array.isArray(hypothesis.sourceWitnessIds) ? hypothesis.sourceWitnessIds : [],
          assumptions: Array.isArray(hypothesis.assumptions) ? hypothesis.assumptions : [],
          missingEvidence: Array.isArray(hypothesis.missingEvidence) ? hypothesis.missingEvidence : [],
          eventSequence: Array.isArray(hypothesis.eventSequence) ? hypothesis.eventSequence : [],
          selectedForSimulation: Boolean(hypothesis.selectedForSimulation),
          notes: typeof hypothesis.notes === "string" ? hypothesis.notes : "",
        }))
      : [],`;
  service = service.replace(anchor, block);
}

if (!service.includes("    hypotheses: [],")) {
  const anchor = "    analysisFindings: [],";
  if (!service.includes(anchor)) fail("createFromCase anchor not found.");
  service = service.replace(anchor, anchor + "\n    hypotheses: [],");
}

if (!service.includes("  addHypothesis(")) {
  const anchor = `  deleteAnalysisFinding(
    investigation: ForensicAccidentInvestigation,
    findingId: string,
  ): ForensicAccidentInvestigation {
    return this.save({
      ...investigation,
      analysisFindings: investigation.analysisFindings.filter((item) => item.id !== findingId),
    });
  },
};`;
  if (!service.includes(anchor)) fail("analysis service tail anchor not found.");
  const block = `  deleteAnalysisFinding(
    investigation: ForensicAccidentInvestigation,
    findingId: string,
  ): ForensicAccidentInvestigation {
    return this.save({
      ...investigation,
      analysisFindings: investigation.analysisFindings.filter((item) => item.id !== findingId),
      hypotheses: investigation.hypotheses.map((hypothesis) => ({
        ...hypothesis,
        supportingFindingIds: hypothesis.supportingFindingIds.filter((id) => id !== findingId),
        conflictingFindingIds: hypothesis.conflictingFindingIds.filter((id) => id !== findingId),
      })),
    });
  },

  addHypothesis(
    investigation: ForensicAccidentInvestigation,
    input: Omit<ForensicCrashHypothesis, "id" | "code" | "createdAt" | "updatedAt">,
  ): ForensicAccidentInvestigation {
    const now = nowIso();
    const record: ForensicCrashHypothesis = {
      ...input,
      provenance: "Investigator Assumption",
      id: createId("crash-hypothesis"),
      code: \`H-\${String(investigation.hypotheses.length + 1).padStart(3, "0")}\`,
      createdAt: now,
      updatedAt: now,
    };
    return this.save({ ...investigation, hypotheses: [...investigation.hypotheses, record] });
  },

  updateHypothesis(
    investigation: ForensicAccidentInvestigation,
    hypothesisId: string,
    patch: Partial<Omit<ForensicCrashHypothesis, "id" | "code" | "createdAt" | "updatedAt" | "provenance">>,
  ): ForensicAccidentInvestigation {
    return this.save({
      ...investigation,
      hypotheses: investigation.hypotheses.map((hypothesis) =>
        hypothesis.id === hypothesisId
          ? { ...hypothesis, ...patch, provenance: "Investigator Assumption", updatedAt: nowIso() }
          : hypothesis,
      ),
    });
  },

  setHypothesisSimulationSelected(
    investigation: ForensicAccidentInvestigation,
    hypothesisId: string,
    selectedForSimulation: boolean,
  ): ForensicAccidentInvestigation {
    const current = investigation.hypotheses.find((item) => item.id === hypothesisId);
    return this.updateHypothesis(investigation, hypothesisId, {
      selectedForSimulation,
      status: selectedForSimulation
        ? "Ready for simulation"
        : current?.status === "Ready for simulation"
          ? "Under review"
          : current?.status,
    });
  },

  deleteHypothesis(
    investigation: ForensicAccidentInvestigation,
    hypothesisId: string,
  ): ForensicAccidentInvestigation {
    return this.save({
      ...investigation,
      hypotheses: investigation.hypotheses.filter((item) => item.id !== hypothesisId),
    });
  },
};`;
  service = service.replace(anchor, block);
}

if (!workspace.includes('import HypothesesWorkspace from "./HypothesesWorkspace";')) {
  const anchor = `import {
  buildForensicAnalysisSignals,
} from "./forensicAnalysisRules";`;
  if (!workspace.includes(anchor)) fail("forensicAnalysisRules import anchor not found.");
  workspace = workspace.replace(anchor, anchor + '\nimport HypothesesWorkspace from "./HypothesesWorkspace";');
}

const activePattern = /const ACTIVE = new Set<Section>\(\[\s*"Overview",[\s\S]*?"Analysis",\s*\]\);/m;
const activeMatch = workspace.match(activePattern);
if (!activeMatch) fail("active section list not found.");
if (!activeMatch[0].includes('"Hypotheses"')) {
  workspace = workspace.replace(activePattern, activeMatch[0].replace('  "Analysis",', '  "Analysis",\n  "Hypotheses",'));
}

if (!workspace.includes('section === "Hypotheses" &&')) {
  const anchor = `          {!ACTIVE.has(section) && (`;
  if (!workspace.includes(anchor)) fail("future-module fallback anchor not found.");
  const block = `          {section === "Hypotheses" && (
            <HypothesesWorkspace
              investigation={investigation}
              onInvestigationChange={setInvestigation}
              onMessage={setMessage}
            />
          )}

`;
  workspace = workspace.replace(anchor, block + anchor);
}

const componentSource = Buffer.from("", "base64").toString("utf8");
const cssSource = Buffer.from("", "base64").toString("utf8");

fs.writeFileSync(TYPES, types, "utf8");
fs.writeFileSync(SERVICE, service, "utf8");
fs.writeFileSync(WORKSPACE, workspace, "utf8");
fs.writeFileSync(COMPONENT, componentSource, "utf8");
fs.writeFileSync(COMPONENT_CSS, cssSource, "utf8");

console.log("\n[RoadSafe] Forensic Hypotheses V1 installed.");
console.log("[RoadSafe] Hypotheses is active after Analysis.");
console.log("[RoadSafe] Competing hypotheses now persist with support/conflict links,");
console.log("[RoadSafe] assumptions, missing evidence, impact regions, event sequence,");
console.log("[RoadSafe] comparison and future simulation selection.");
console.log("[RoadSafe] Backup: " + path.relative(ROOT, backupDir));
console.log("\nRun: npm run build");
